// Parity with the reference scorer of the private pack (engineering spec, section 12.2).
// The vectors are generated by `python3 tools/lab_scoring.py --vectors` and never edited by hand.
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { fourMetricScore, normalize } from '../src/index.ts'

type Vector = { request: Record<string, unknown> & { fn: string }; expected: Record<string, unknown> }
const file = JSON.parse(readFileSync(new URL('./vectors/reference.json', import.meta.url), 'utf8')) as {
  packs: Record<string, unknown>; vectors: Vector[]
}
const expand = (x: unknown): unknown => {
  if (typeof x === 'string' && x.startsWith('@')) return file.packs[x.slice(1)]
  if (Array.isArray(x)) return x.map(expand)
  if (x && typeof x === 'object') return Object.fromEntries(Object.entries(x).map(([k, v]) => [k, expand(v)]))
  return x
}
const byFn = (fn: string) => file.vectors.filter((v) => v.request.fn === fn).map((v) => ({ ...v, request: expand(v.request) as Vector['request'] }))

describe('parity: normalization', () => {
  const vs = byFn('normalize')
  it('has vectors', () => expect(vs.length).toBeGreaterThan(10))
  for (const [i, v] of vs.entries()) {
    it(`normalize #${i}`, () => {
      const r = v.request as unknown as { raw: number; anchors: { zero: number; floor: number; ceiling: number }; norm: { floor_points: number; max_points: number } }
      if ('error' in v.expected) expect(() => normalize(r.raw, r.anchors, r.norm)).toThrow()
      else expect(normalize(r.raw, r.anchors, r.norm)).toBe(v.expected.points)
    })
  }
})

describe('parity: the four-metric score', () => {
  for (const [i, v] of byFn('four_metric').entries()) {
    it(`four_metric #${i}`, () => {
      const r = v.request as unknown as { v: number; r: number; c: number; x: number; cfg: { weights: { validity: number; reliability: number; cost: number; complexity: number } } }
      expect(Math.abs(fourMetricScore(r.v, r.r, r.c, r.x, r.cfg.weights) - (v.expected.score as number))).toBeLessThan(1e-9)
    })
  }
})

